```tsx
import { useId } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps) {
  const labelId = useId();
  const hintId = useId();

  return (
    <div className="settings-toggle-row">
      <div className="settings-toggle-row__text">
        <span id={labelId} className="settings-toggle-row__label">
          {label}
        </span>
        <span id={hintId} className="settings-toggle-row__hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        className="settings-toggle-row__switch"
        aria-pressed={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        onClick={() => onChange(!checked)}
      >
        <span className="settings-toggle-row__knob" aria-hidden="true" />
      </button>
    </div>
  );
}
```

```css
.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(12px, 2vw, 24px);
  padding: clamp(10px, 1.4vw, 16px) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.settings-toggle-row__label {
  display: block;
  font-size: clamp(14px, 1.1vw + 8px, 18px);
  font-weight: 600;
  color: var(--ink);
}

.settings-toggle-row__hint {
  display: block;
  font-size: clamp(12px, 0.9vw + 6px, 15px);
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  position: relative;
  flex-shrink: 0;
  box-sizing: border-box;
  width: 48px;
  height: 28px;
  margin: 0;
  padding: 3px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: var(--slide);
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}

.settings-toggle-row__switch[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.settings-toggle-row__knob {
  display: block;
  width: 20px;
  height: 20px;
  border-radius: 999px;
  background: var(--muted);
  transition: transform 160ms ease, background-color 160ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] .settings-toggle-row__knob {
  background: var(--slide);
  transform: translateX(20px);
}

:root[data-motion="reduce"] .settings-toggle-row__knob {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__knob {
    transition: none;
  }
}
